window.ANGI_PROMPT = (target) => {
  const id = target && target.id;
  if (!Object.hasOwn(angiSourceProfiles, id)) return 'STOP: no supported source install profile for this target. Do not build or write media.';
  const profile = angiSourceProfiles[id];
  return angiSourceTemplate.replace(/{{(\w+)}}/g, (_, key) => profile[key]) + '\n\n' + angiFirstBoot[id];
};
